// Keeps short, high-view clips and turns them into the list shown on the form.
// RankReel takes clips up to 60 seconds. A lower default keeps out compilations, which tend to run the full minute.
const LONGEST_ALLOWED = 60;
const DEFAULT_MAX_SECONDS = 30;
const DEFAULT_MIN_VIEWS = 500000;
const MAX_LINKS = 15;
// A ranking needs 5 to 7 clips, so a thin result is topped up with short clips that missed the view minimum.
const TOP_UP_TO = 10;

const form = $('Type a keyword').first().json;
const keyword = String(form['Keyword'] ?? '').trim();
const minViews = Number(form['Minimum views']) > 0 ? Number(form['Minimum views']) : DEFAULT_MIN_VIEWS;
const askedSeconds = Number(form['Maximum seconds']);
const maxSeconds = askedSeconds > 0 ? Math.min(askedSeconds, LONGEST_ALLOWED) : DEFAULT_MAX_SECONDS;
const results = $input.all().map((item) => item.json);

const escapeHtml = (value) =>
  String(value ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const compact = (n) =>
  n >= 1e6 ? `${(n / 1e6).toFixed(1).replace(/\.0$/, '')}M` : n >= 1e3 ? `${Math.round(n / 1e3)}K` : String(n);
const clock = (s) => `${Math.floor(s / 60)}:${String(Math.round(s % 60)).padStart(2, '0')}`;

const page = (body) =>
  `<div style="max-width:680px;margin:48px auto;padding:0 20px;font:16px/1.5 system-ui,-apple-system,Segoe UI,sans-serif;color:#0f1a33">${body}<p style="margin-top:28px"><a href="/form/viral-clips" style="color:#2447f9;font-weight:600">Search again</a></p></div>`;

const failed = results.find((r) => r.error);
if (failed) {
  const reason = typeof failed.error === 'string' ? failed.error : failed.error.message || 'Unknown error';
  const tokenProblem = /401|403|token|authenticat|authoriz/i.test(reason);
  const html = page(
    tokenProblem
      ? '<h2>Apify did not accept the token</h2><p>Open Credentials in n8n, edit "Apify token" and make sure the value is the word Bearer, a space, then your Apify API token.</p>'
      : `<h2>The search did not run</h2><p>${escapeHtml(reason.slice(0, 240))}</p><p>Wait a minute and search again. If it keeps failing, check your remaining credit at console.apify.com.</p>`,
  );
  return [{ json: { keyword, count: 0, html, clips: [] } }];
}

const seen = new Set();
const shortEnough = results
  .filter((r) => r.webVideoUrl && !r.isSlideshow && !seen.has(r.webVideoUrl) && seen.add(r.webVideoUrl))
  .map((r) => ({
    url: r.webVideoUrl,
    views: Number(r.playCount) || 0,
    likes: Number(r.diggCount) || 0,
    seconds: Number(r.videoMeta?.duration) || 0,
    author: r.authorMeta?.name || '',
    caption: String(r.text || '').replace(/\s+/g, ' ').trim().slice(0, 100),
    posted: String(r.createTimeISO || '').slice(0, 10),
  }))
  .filter((c) => c.seconds > 0 && c.seconds <= maxSeconds)
  .sort((a, b) => b.views - a.views);

const clips = shortEnough.filter((c) => c.views >= minViews).slice(0, MAX_LINKS);
const belowMinimum = shortEnough.filter((c) => c.views < minViews).slice(0, Math.max(0, TOP_UP_TO - clips.length));

const heading = `<h2>${clips.length} ${clips.length === 1 ? 'clip' : 'clips'} for "${escapeHtml(keyword)}"</h2>`;
const summary = `<p>At least ${compact(minViews)} views, ${maxSeconds} seconds or shorter, most viewed first. Checked ${results.length} search results.</p>`;
const rows = (items) =>
  items
      .map(
        (c) =>
          `<li style="margin-bottom:14px"><a href="${escapeHtml(c.url)}" target="_blank" rel="noopener" style="color:#2447f9;font-weight:600">${compact(c.views)} views</a>, ${clock(c.seconds)}, @${escapeHtml(c.author)}<br><span style="color:#46536e">${escapeHtml(c.caption)}</span></li>`,
      )
      .join('');

const list = clips.length ? `<ol>${rows(clips)}</ol>` : '';
const extra = belowMinimum.length
  ? `<h3>${belowMinimum.length} more under ${compact(minViews)} views</h3><p>Short enough, but below your minimum. Most viewed first.</p><ol start="${clips.length + 1}">${rows(belowMinimum)}</ol>`
  : '';
const nothing = clips.length || belowMinimum.length
  ? ''
  : '<p>Nothing matched. Search again with a longer maximum, a broader keyword or more results to check.</p>';

return [{ json: { keyword, count: clips.length, html: page(heading + summary + list + extra + nothing), clips, belowMinimum } }];
